#include <cstddef>

std::size_t count_commas(const char* begin, const char* const end) {
    std::size_t commas = 0;
    for (const char* cursor = begin; cursor != end; ++cursor) {
        if (*cursor == ',') {
            ++commas;
        }
    }
    return commas;
}

std::size_t count_commas(const char (&line)[64]) {
    return count_commas(line, line + sizeof(line));
}

#include <cstdint>
#include <utility>

enum class TokenKind : std::uint8_t {
    Invalid = 0,
    Word = 1,
    Number = 2,
    Punct = 3
};

std::uint8_t to_wire(TokenKind kind) {
    return std::to_underlying(kind);
}

TokenKind from_wire(std::uint8_t byte) {
    switch (byte) {
        case 1:
            return TokenKind::Word;
        case 2:
            return TokenKind::Number;
        case 3:
            return TokenKind::Punct;
        default:
            return TokenKind::Invalid;
    }
}

#include <cstddef>

bool fits(std::size_t used, std::size_t capacity, std::size_t incoming) {
    if (used > capacity) {
        return false;  // broken invariant: never subtract into a wrap
    }
    return incoming <= capacity - used;
}

#include <cmath>

// An ordered comparison with NaN is false, so a lone "if (c > 85.0) return
// false;" lets a NaN through as in-range. Test finiteness first.
bool is_valid_reading(double celsius) {
    if (!std::isfinite(celsius)) {
        return false;
    }
    return celsius >= -60.0 && celsius <= 85.0;
}

int to_decidegrees(double celsius) {
    return static_cast<int>(std::lround(celsius * 10.0));
}

#include <cmath>
