static_assert(std::numeric_limits<double>::is_iec559);

double decay(double level, double factor) {
    double next = level * factor;
    if (std::abs(next) < std::numeric_limits<double>::min()) {
        return 0.0;  // flush subnormal results; keeps the update off the assist path
    }
    return next;
}

