constexpr int kMonthLength[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
static_assert(sizeof(kMonthLength) / sizeof(kMonthLength[0]) == 12);

int day_of_year(int month, int day) {  // month is 1-based
    int total = day;
    for (int m = 1; m < month; ++m) {
        total += kMonthLength[m - 1];
    }
    return total;
}

#include <cstddef>
#include <cstdint>

struct Config {
    int level;
};

extern "C" void legacy_log(void* context, const char* text, std::size_t len);

void forward(void* payload, std::size_t len, const Config* config) {
    // void* to an object pointer type: a plain type-system conversion.
    const char* text = static_cast<const char*>(payload);

    // Changes cv-qualification only; the address and value are untouched.
    void* context = const_cast<Config*>(config);

    // Reinterprets the pointer's representation as an integer.
    std::uintptr_t id = reinterpret_cast<std::uintptr_t>(payload);
    (void)id;

    legacy_log(context, text, len);

    // The const_cast is legal here, but if legacy_log writes through the
    // context and the underlying Config was defined const, that write is
    // undefined behaviour — removing const does not make the object writable.
}

#include <iostream>
#include <vector>

void double_in_place(std::vector<int>& ring) {
    for (auto& slot : ring) {  // auto& aliases the element
        slot *= 2;
    }
}

void print_all(const std::vector<int>& ring) {
    for (const auto& slot : ring) {  // observes without copying
        std::cout << slot << ' ';
    }
    std::cout << '\n';

    // for (auto slot : ring) { slot *= 2; }
    // Plain auto drops the reference: slot is a copy of the element, so the
    // multiplication updates the copy and the container is unchanged.
}
